mapper.select:
-- Select standard codes by group and optional keyword. SELECT sc.id AS standard_code_id, scg.group_code, scg.group_name, sc.code, sc.code_name, sc.parent_code, sc.level_no, sc.sort_order, sc.is_active AS active FROM standard_codes sc INNER JOIN standard_code_groups scg ON scg.id = sc.group_id WHERE scg.group_code = #{groupCode}
AND sc.is_active = #{active}
AND ( sc.code ILIKE concat('%', #{keyword}, '%') OR sc.code_name ILIKE concat('%', #{keyword}, '%') )
ORDER BY sc.sort_order ASC, sc.code ASC LIMIT #{size} OFFSET #{offset}

-- Count standard codes by group and optional keyword. SELECT count(1) FROM standard_codes sc INNER JOIN standard_code_groups scg ON scg.id = sc.group_id WHERE scg.group_code = #{groupCode}
AND sc.is_active = #{active}
AND ( sc.code ILIKE concat('%', #{keyword}, '%') OR sc.code_name ILIKE concat('%', #{keyword}, '%') )
